            text = xlsx_to_csv_text(content, max_rows)
        elif lowered.endswith('.csv'):
            text = content.decode('utf-8-sig')
        else:
            return [], [{'row': 0, 'errors': ['unsupported file type; upload .xlsx or .csv']}]
    except Exception:
